using SmartInventoryArrange.Core;
using System.Text.Json;
int checks=0;void Check(string name,bool v){if(!v)throw new Exception(name);checks++;}
var rect=new ShapeMask(new[]{new Cell(0,0),new Cell(0,1)});var flat=rect.Rotate90();
LayoutItem I(string id,int x,int code=0)=>new(){StableId=id,ItemId="same",PrimaryCategory="ENERGY_CELL",Categories=new[]{"ENERGY_CELL"},OriginalX=x,OriginalY=2,OriginalOrientation=code,Orientations=new[]{new Orientation(code,rect,false),new Orientation(code+1,flat,true)}};
var items=new[]{I("same\u001f2",3,2),I("same\u001f1",0)};var usable=new bool[5,5];for(int y=0;y<5;y++)for(int x=0;x<5;x++)usable[x,y]=true;usable[4,0]=false;var fixeds=new[]{new Placement("fixed",4,4,0,new ShapeMask(new[]{new Cell(0,0)}),"ENERGY_CELL",false)};var problem=new LayoutProblem{Width=5,Height=5,Usable=usable,Items=items,Fixed=fixeds,CategoryOrder=new Dictionary<string,int>{{"ENERGY_CELL",0}}};var original=items.Select(i=>new Placement(i.StableId,i.OriginalX,i.OriginalY,i.OriginalOrientation,rect,i.PrimaryCategory,false)).ToArray();var before=Native34Solver.Key(original);var solver=new Native34Solver();var a=solver.Solve(problem,original);Check("valid",a.Complete&&Native34Solver.ValidateLayout(problem,a.Placements));Check("all-preserved",a.Placements.Select(q=>q.StableId).OrderBy(x=>x).SequenceEqual(items.Select(i=>i.StableId).OrderBy(x=>x)));Check("source-not-mutated",Native34Solver.Key(original)==before);Check("fixed-unchanged",fixeds[0].X==4&&fixeds[0].Y==4);Check("original-item-model-unchanged",items[0].OriginalX==3&&items[0].OriginalOrientation==2);Check("zeroed-time-budget-not-required",!a.TimedOut);Check("repeat",Native34Solver.SameLayout(a.Placements,new Native34Solver().Solve(problem,a.Placements).Placements));
var rev=new LayoutProblem{Width=5,Height=5,Usable=usable,Items=items.Reverse().ToArray(),Fixed=fixeds,CategoryOrder=problem.CategoryOrder};Check("input-order",Native34Solver.SameLayout(a.Placements,new Native34Solver().Solve(rev,original.Reverse().ToArray()).Placements));
var mutations=new List<(string,Placement[])>{("missing",a.Placements.Skip(1).ToArray()),("duplicate",a.Placements.Append(a.Placements[0]).ToArray()),("id",a.Placements.Select((q,i)=>i==0?q with{StableId="bad"}:q).ToArray()),("negative",a.Placements.Select((q,i)=>i==0?q with{X=-1}:q).ToArray()),("bound",a.Placements.Select((q,i)=>i==0?q with{Y=5}:q).ToArray()),("orientation",a.Placements.Select((q,i)=>i==0?q with{GameOrientation=99}:q).ToArray()),("mask",a.Placements.Select((q,i)=>i==0?q with{Mask=new ShapeMask(new[]{new Cell(0,0)})}:q).ToArray()),("category",a.Placements.Select((q,i)=>i==0?q with{Category="bad"}:q).ToArray()),("fixed-collision",a.Placements.Select((q,i)=>i==0?q with{X=4,Y=3}:q).ToArray()),("disabled",a.Placements.Select((q,i)=>i==0?q with{X=4,Y=0}:q).ToArray())};
foreach(var (name,q) in mutations)Check("reject-"+name,!Native34Solver.ValidateLayout(problem,q));
Check("reject-mismatched-mask-and-original-code",!Native34Solver.ValidateLayout(problem,a.Placements.Select(q=>q with{GameOrientation=items.Single(i=>i.StableId==q.StableId).OriginalOrientation,Mask=flat}).ToArray()));
Check("different-orientation-numbers",a.Placements.All(q=>items.Single(i=>i.StableId==q.StableId).Orientations.Any(o=>o.GameOrientation==q.GameOrientation&&o.Mask.Signature==q.Mask.Signature)));
var capped=new Native34Solver{MaxPasses=1}.Solve(problem,original);Check("global-no-old-fixedpoint-veto",!capped.UsedFallback&&Native34Solver.ValidateLayout(problem,capped.Placements));
foreach(var bad in mutations.Take(7)){bool raised=false;try{new Native34Solver().Solve(problem,bad.Item2);}catch(ArgumentException){raised=true;}Check("invalid-input-"+bad.Item1,raised);}
for(int width=1;width<=6;width++)for(int height=2;height<=8;height+=2){var u=new bool[width,height];for(int y=0;y<height;y++)for(int x=0;x<width;x++)u[x,y]=true;var one=I("same\u001f1",0);one=new(){StableId=one.StableId,ItemId=one.ItemId,PrimaryCategory=one.PrimaryCategory,Categories=one.Categories,Orientations=one.Orientations,OriginalOrientation=0,OriginalX=0,OriginalY=0};var p=new LayoutProblem{Width=width,Height=height,Usable=u,Items=new[]{one}};var q=new[]{new Placement(one.StableId,0,0,0,rect,one.PrimaryCategory,false)};var r=new Native34Solver().Solve(p,q);Check($"size-{width}x{height}",r.Complete&&Native34Solver.ValidateLayout(p,r.Placements));}
var empty=new LayoutProblem{Width=1,Height=1,Usable=new bool[,]{{true}}};Check("empty",new Native34Solver().Solve(empty,Array.Empty<Placement>()).Complete);
Console.WriteLine($"SAFETY_NATIVE checks={checks}/{checks} immutable=True fixed=True orientationMapping=True deterministic=True exit=0");
